script:
frappe.ui.form.on('Index Set', {
	muc_tieu_chuan_hoa: function(frm, cdt, cdn) {
		calculate_diem_chuan_hoa(frm, cdt, cdn);
		calculate_tong_diem_chuan_hoa(frm);
	},
	thuc_hien: function(frm, cdt, cdn) {
		calculate_diem_chuan_hoa(frm, cdt, cdn);
		calculate_tong_diem_chuan_hoa(frm);
	},
	diem_chuan_hoa: function(frm, cdt, cdn) {
	    calculate_tong_diem_chuan_hoa(frm);
	},
	refresh: function(frm) {
        caluclate_tong_diem_co_so(frm);
    }
});

// TÍNH ĐIỂM CHUẨN HÓA Ở CÁC BẢNG CON
function calculate_diem_chuan_hoa(frm, cdt, cdn) {
    let d = locals[cdt][cdn];
    let muc_tieu_chuan_hoa = parseFloat(d.muc_tieu_chuan_hoa) || 0;
    let diem_co_so = parseFloat(d.diem_co_so) || 0;
    let thuc_hien = parseFloat(d.thuc_hien) || 0;
    
    if (muc_tieu_chuan_hoa > 0 && thuc_hien >= 0) {
        d.diem_chuan_hoa = (thuc_hien >= muc_tieu_chuan_hoa) 
            ? diem_co_so 
            : (thuc_hien / muc_tieu_chuan_hoa) * diem_co_so;
    } else {
        d.diem_chuan_hoa = 0;
    }
    
    frm.refresh_field("bang_nhan_thuc_so_va_the_che_so");
    frm.refresh_field("bang_ha_tang_va_an_ninh_mang");
    frm.refresh_field("bang_nhan_luc_so");
    frm.refresh_field("bang_hoat_dong_kinh_te_so");
}

// TÍNH TỔNG ĐIỂM CHUẨN HÓA
function calculate_tong_diem_chuan_hoa(frm) {
    let tong_diem_nhan_thuc_so_va_the_che_so = 0;
    let tong_diem_ha_tang_va_an_ninh_mang = 0;
    let tong_diem_nhan_luc_so = 0;
    let tong_diem_hoat_dong_kinh_te_so = 0;
    
    frm.doc.bang_nhan_thuc_so_va_the_che_so.forEach(row => {
        if (row.diem_chuan_hoa) {
            tong_diem_nhan_thuc_so_va_the_che_so += row.diem_chuan_hoa;
        }
    });
    
    frm.doc.bang_ha_tang_va_an_ninh_mang.forEach(row => {
        if (row.diem_chuan_hoa) {
            tong_diem_ha_tang_va_an_ninh_mang += row.diem_chuan_hoa;
        }
    });
    
    frm.doc.bang_nhan_luc_so.forEach(row => {
        if (row.diem_chuan_hoa) {
            tong_diem_nhan_luc_so += row.diem_chuan_hoa;
        }
    });
    
    frm.doc.bang_hoat_dong_kinh_te_so.forEach(row => {
        if (row.diem_chuan_hoa) {
            tong_diem_hoat_dong_kinh_te_so += row.diem_chuan_hoa;
        }
    });
    
    frm.set_value("tong_diem_nhan_thuc_so_va_the_che_so", tong_diem_nhan_thuc_so_va_the_che_so);
    frm.set_value("tong_diem_ha_tang_va_an_ninh_mang", tong_diem_ha_tang_va_an_ninh_mang);
    frm.set_value("tong_diem_nhan_luc_so", tong_diem_nhan_luc_so);
    frm.set_value("tong_diem_hoat_dong_kinh_te_so", tong_diem_hoat_dong_kinh_te_so)
}

//TÍNH TỔNG ĐIỂM CƠ SỞ
function caluclate_tong_diem_co_so(frm) {
    let tong_diem_co_so_bang_nhan_thuc_so_va_the_che_so = 0;
    let tong_diem_co_so_ha_tang_va_an_ninh_mang = 0;
    let tong_diem_co_so_nhan_luc_so = 0;
    let tong_diem_co_so_hoat_dong_kinh_te_so = 0;

    frm.doc.bang_nhan_thuc_so_va_the_che_so.forEach(row => {
        if (row.diem_co_so) {
            tong_diem_co_so_bang_nhan_thuc_so_va_the_che_so += row.diem_co_so;
        }
    });
    
    frm.doc.bang_ha_tang_va_an_ninh_mang.forEach(row => {
        if (row.diem_co_so) {
            tong_diem_co_so_ha_tang_va_an_ninh_mang += row.diem_co_so;
        }
    });
    
    frm.doc.bang_nhan_luc_so.forEach(row => {
        if (row.diem_co_so) {
            tong_diem_co_so_nhan_luc_so += row.diem_co_so;
        }
    });
    
    frm.doc.bang_hoat_dong_kinh_te_so.forEach(row => {
        if (row.diem_co_so) {
            tong_diem_co_so_hoat_dong_kinh_te_so += row.diem_co_so;
        }
    });
    
    frm.set_value('tong_diem_co_so_bang_nhan_thuc_so_va_the_che_so', tong_diem_co_so_bang_nhan_thuc_so_va_the_che_so);
    frm.set_value('tong_diem_co_so_ha_tang_va_an_ninh_mang', tong_diem_co_so_ha_tang_va_an_ninh_mang);
    frm.set_value('tong_diem_co_so_nhan_luc_so', tong_diem_co_so_nhan_luc_so);
    frm.set_value('tong_diem_co_so_hoat_dong_kinh_te_so', tong_diem_co_so_hoat_dong_kinh_te_so);
}

frappe.ui.form.on('Index Set', {
	gia_tri_thanh_phan_a: function(frm, cdt, cdn) {
		calculate_gia_tri_tham_chieu(frm, cdt, cdn);
	},
	gia_tri_thanh_phan_b: function(frm, cdt, cdn) {
		calculate_gia_tri_tham_chieu(frm, cdt, cdn);
	}
});

function calculate_gia_tri_tham_chieu(frm, cdt, cdn) {
    let d = locals[cdt][cdn];
    let gia_tri_a = parseFloat(d.gia_tri_thanh_phan_a) || 0;
    let gia_tri_b = parseFloat(d.gia_tri_thanh_phan_b) || 0;
    if (gia_tri_b !== 0) {
        d.gia_tri_tham_chieu = (gia_tri_a / gia_tri_b) * 100;
    } else {
        d.gia_tri_tham_chieu = 0;
    }
    frm.refresh_field("bang_nhan_thuc_so_va_the_che_so");
    frm.refresh_field("bang_ha_tang_va_an_ninh_mang");
    frm.refresh_field("bang_nhan_luc_so");
    frm.refresh_field("bang_hoat_dong_kinh_te_so");
}

frappe.ui.form.on('Digital Economy Index Set', {
    onload: function(frm) {
        if (frm.is_new()) {
            // Xóa tất cả bảng con
            const tables = [
                "bang_nhan_thuc_so_va_the_che_so",
                "bang_ha_tang_va_an_ninh_mang",
                "bang_nhan_luc_so",
                "bang_hoat_dong_kinh_te_so",
                "bang_doanh_thu_nganh_kts"
            ];
            tables.forEach(table => frm.clear_table(table));
            // Danh sách các bộ chỉ số và bảng tương ứng
            const chiSoMapping = [
                { bo_chi_so: "Nhận thức số và thể chế số", table: "bang_nhan_thuc_so_va_the_che_so" },
                { bo_chi_so: "Hạ tầng số và an ninh mạng", table: "bang_ha_tang_va_an_ninh_mang" },
                { bo_chi_so: "Nhân lực số", table: "bang_nhan_luc_so" },
                { bo_chi_so: "Hoạt động Kinh tế số", table: "bang_hoat_dong_kinh_te_so" },
                { bo_chi_so: "Doanh thu các ngành KTS", table: "bang_doanh_thu_nganh_kts" }
            ];
            // Hàm tái sử dụng để lấy dữ liệu và thêm vào bảng con
            const fetchAndAddToTable = function(bo_chi_so, table) {
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Index Name",
                        filters: { bo_chi_so: bo_chi_so },
                        fields: ["ten_chi_so", "so_thu_tu"],
                        order_by: "so_thu_tu asc"
                    },
                    callback: function(response) {
                        if (response.message) {
                            let index_list = response.message;

                            index_list.forEach(record => {
                                frm.add_child(table, {
                                    ten_chi_so: record.ten_chi_so,
                                });
                            });

                            // Làm mới bảng con
                            frm.refresh_field(table);
                        }
                    }
                });
            };
            // Thực hiện gọi hàm cho từng bộ chỉ số và bảng con
            chiSoMapping.forEach(mapping => {
                fetchAndAddToTable(mapping.bo_chi_so, mapping.table);
            });
        }
    }
});

frappe.ui.form.on('Digital Economy Index Set', {
    quy: function(frm) {
        update_time(frm);
    },
    nam: function(frm) {
        update_time(frm);
    },
});

function update_time(frm) {
    let thang_map = { "Q1": "01", "Q2": "04", "Q3": "07", "Q4": "10" };
    let thang = thang_map[frm.doc.quy] || "01";
    let thoi_gian_moi = `${frm.doc.nam}-${thang}-01`;
    if (frm.doc.thoi_gian !== thoi_gian_moi) {
        frm.set_value("thoi_gian", thoi_gian_moi);
    }
}

frappe.ui.form.on('Index Set', {
    muc_tieu_chuan_hoa: function(frm, cdt, cdn) {
        calculate_diem_chuan_hoa(frm, cdt, cdn);
        calculate_tong_diem_chuan_hoa(frm);
    },
    gia_tri_tham_chieu: function(frm, cdt, cdn) {
        calculate_diem_chuan_hoa(frm, cdt, cdn);
        calculate_tong_diem_chuan_hoa(frm);
    },
    diem_chuan_hoa: function(frm, cdt, cdn) {
        calculate_tong_diem_chuan_hoa(frm);
    },
});

frappe.ui.form.on('Digital Economy Index Set', {
    validate: function(frm) {
        calculate_all_totals(frm);
    }
});

// TÍNH ĐIỂM CHUẨN HÓA Ở CÁC BẢNG CON
function calculate_diem_chuan_hoa(frm, cdt, cdn) {
    let d = locals[cdt][cdn];
    let muc_tieu_chuan_hoa = parseFloat(d.muc_tieu_chuan_hoa) || 0;
    let diem_co_so = parseFloat(d.diem_co_so) || 0;
    let gia_tri_tham_chieu = parseFloat(d.gia_tri_tham_chieu) || 0;

    if (muc_tieu_chuan_hoa > 0 && gia_tri_tham_chieu >= 0) {
        d.diem_chuan_hoa = (gia_tri_tham_chieu >= muc_tieu_chuan_hoa)
            ? diem_co_so
            : (gia_tri_tham_chieu / muc_tieu_chuan_hoa) * diem_co_so;
    } else {
        d.diem_chuan_hoa = 0;
    }

    refresh_child_tables(frm);
}

// TÍNH TỔNG ĐIỂM CƠ SỞ VÀ ĐIỂM CHUẨN HÓA
function calculate_all_totals(frm) {
    calculate_total_for_tables(frm, "diem_co_so", {
        "bang_nhan_thuc_so_va_the_che_so": "tong_diem_co_so_bang_nhan_thuc_so_va_the_che_so",
        "bang_ha_tang_va_an_ninh_mang": "tong_diem_co_so_ha_tang_va_an_ninh_mang",
        "bang_nhan_luc_so": "tong_diem_co_so_nhan_luc_so",
        "bang_hoat_dong_kinh_te_so": "tong_diem_co_so_hoat_dong_kinh_te_so"
    });

    calculate_total_for_tables(frm, "diem_chuan_hoa", {
        "bang_nhan_thuc_so_va_the_che_so": "tong_diem_nhan_thuc_so_va_the_che_so",
        "bang_ha_tang_va_an_ninh_mang": "tong_diem_ha_tang_va_an_ninh_mang",
        "bang_nhan_luc_so": "tong_diem_nhan_luc_so",
        "bang_hoat_dong_kinh_te_so": "tong_diem_hoat_dong_kinh_te_so"
    });
}

// TÍNH TỔNG DÙNG CHUNG
function calculate_total_for_tables(frm, field, table_to_total_map) {
    Object.keys(table_to_total_map).forEach(table => {
        let total = 0;

        if (frm.doc[table]) {
            frm.doc[table].forEach(row => {
                total += parseFloat(row[field]) || 0;
            });
        }

        frm.set_value(table_to_total_map[table], total);
    });
}

// LÀM MỚI BẢNG CON
function refresh_child_tables(frm) {
    frm.refresh_field("bang_nhan_thuc_so_va_the_che_so");
    frm.refresh_field("bang_ha_tang_va_an_ninh_mang");
    frm.refresh_field("bang_nhan_luc_so");
    frm.refresh_field("bang_hoat_dong_kinh_te_so");
}
